def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_ids(a, b):
        for x, y in zip(a, b):
            xd, yd = x.isdigit(), y.isdigit()
            if xd and yd:
                xv, yv = int(x), int(y)
                if xv != yv:
                    return -1 if xv < yv else 1
            elif xd and not yd:
                return -1
            elif not xd and yd:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def cmp(v1, v2):
        m1, n1, p1, pre1 = parse(v1)
        m2, n2, p2, pre2 = parse(v2)
        if (m1, n1, p1) != (m2, n2, p2):
            return -1 if (m1, n1, p1) < (m2, n2, p2) else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        return cmp_ids(pre1, pre2)

    import functools
    return sorted(versions, key=functools.cmp_to_key(cmp))

